// Bounded, cold-process comparison owned by chat 01a13e18-e061-7930-8a81-af528c1d37d5.
[InitializeOnLoad]
public static class NativeShaderPerformanceAudit
{
    const string Key="SushiAndFish.NativeShaderPerf.";
    static string Reports=>IslandRevision20261018.Reports;
    [Serializable] public class Sample {public string name; public int frames; public double seconds,fps,p50ms,p95ms,scanMs,scanMsPerFrame,mainThreadMs,renderThreadMs,gpuMs,drawCalls; public long scans; public int renderers,materials;}
    [Serializable] public class Result {public string utc,version,profile,stage,error,gpu,api;public int width,height,shaders,appliedMaterials,unrestoredMaterials;public bool ready,passed,lateMaterialRestored,saveBoundaryRetained,sceneEventRestored,mapUpdates,waterComputeRestored,targetedMaterialRestored,diskMaterialRetained;public string saveAuthoringState,saveReappliedState;public string[] errors;public List<Sample> samples=new List<Sample>();}
    static Result result;static double finish;static bool exiting;
    static readonly List<string> errors=new List<string>();
    static NativeShaderPerformanceAudit(){if(SessionState.GetBool(Key+"active",false)){EditorApplication.update+=Tick;Application.logMessageReceived+=Collect;}}
    public static void StartBaseline()=>Start("baseline");
    public static void StartFixed()=>Start("fixed");
    static void Start(string version){SessionState.SetString(Key+"version",version);SessionState.SetBool(Key+"active",true);SessionState.SetBool(Key+"started",false);SessionState.SetBool(Key+"done",false);if(!AssetDatabase.IsValidFolder("Assets/RecoveryVerification"))AssetDatabase.CreateFolder("Assets","RecoveryVerification");PlayerSettings.productName="SushiAndFish WorldRepair QA 20261016";EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");EditorApplication.update+=Tick;Application.logMessageReceived+=Collect;EditorApplication.EnterPlaymode();}
    static void Collect(string message,string stack,LogType type){if((type==LogType.Error||type==LogType.Exception||type==LogType.Assert)&&errors.Count<30)errors.Add(message+"\n"+stack);}
    static object Prior(string name)=>typeof(WorldIssuePlayAudit).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);
    static void Write(){result.errors=errors.ToArray();File.WriteAllText(Path.Combine(Reports,"native-shader-performance-"+result.version+".json"),JsonUtility.ToJson(result,true));}
    static void Tick(){if(EditorApplication.isPlaying&&Application.isPlaying&&!SessionState.GetBool(Key+"started",false)){SessionState.SetBool(Key+"started",true);Run().Forget();}if(!EditorApplication.isPlayingOrWillChangePlaymode&&SessionState.GetBool(Key+"done",false)&&!exiting){exiting=true;var file=Path.Combine(Reports,"native-shader-performance-"+SessionState.GetString(Key+"version","")+".json");result=JsonUtility.FromJson<Result>(File.ReadAllText(file));result.errors=errors.ToArray();result.passed=result.ready&&string.IsNullOrEmpty(result.error)&&errors.Count==0&&(result.version=="baseline"||(result.samples.All(s=>s.scans==0)&&result.lateMaterialRestored&&result.targetedMaterialRestored&&result.diskMaterialRetained&&result.sceneEventRestored&&result.saveBoundaryRetained&&result.waterComputeRestored&&result.mapUpdates&&result.unrestoredMaterials==0));result.stage=result.passed?"PASS":"FAILED";Write();PlayerSettings.productName="Deep Blue Sushi";EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");AssetDatabase.SaveAssets();finish=EditorApplication.timeSinceStartup;}if(exiting&&EditorApplication.timeSinceStartup-finish>4)EditorApplication.Exit(result.passed?0:1);}
    static async UniTask Pause(double seconds)=>await UniTask.Delay(TimeSpan.FromSeconds(seconds),ignoreTimeScale:true);
    static async UniTask Wait(Func<bool> predicate,int seconds=210){var end=DateTime.UtcNow.AddSeconds(seconds);while(!predicate()){if(DateTime.UtcNow>end)throw new TimeoutException(result.stage);await UniTask.Yield();}}
    static async UniTask SampleFrames(string name){await Pause(2);result.stage=name;Write();var durations=new List<double>();var sampler=UnityEngine.Object.FindFirstObjectByType<RuntimePerformanceSampler>();double main=0,render=0,gpu=0,draw=0;int telemetry=0;long scans=OriginalNativeShaderRestoration.ScanCount;double cost=OriginalNativeShaderRestoration.TotalScanMilliseconds;double start=Time.realtimeSinceStartupAsDouble,previous=start;while(Time.realtimeSinceStartupAsDouble-start<6){await UniTask.Yield(PlayerLoopTiming.LastPostLateUpdate);double now=Time.realtimeSinceStartupAsDouble;durations.Add((now-previous)*1000);previous=now;if(sampler&&sampler.Latest!=null){main+=sampler.Latest.mainThreadMs;render+=sampler.Latest.renderThreadMs;gpu+=sampler.Latest.gpuMs;draw+=sampler.Latest.drawCalls;telemetry++;}await UniTask.NextFrame();}double elapsed=Time.realtimeSinceStartupAsDouble-start;durations.Sort();result.samples.Add(new Sample{name=name,frames=durations.Count,seconds=elapsed,fps=durations.Count/elapsed,p50ms=durations[durations.Count/2],p95ms=durations[Math.Min(durations.Count-1,(int)(durations.Count*.95))],scans=OriginalNativeShaderRestoration.ScanCount-scans,scanMs=OriginalNativeShaderRestoration.TotalScanMilliseconds-cost,scanMsPerFrame=(OriginalNativeShaderRestoration.TotalScanMilliseconds-cost)/durations.Count,mainThreadMs=telemetry>0?main/telemetry:0,renderThreadMs=telemetry>0?render/telemetry:0,gpuMs=telemetry>0?gpu/telemetry:0,drawCalls=telemetry>0?draw/telemetry:0,renderers=OriginalNativeShaderRestoration.LastRendererCount,materials=OriginalNativeShaderRestoration.LastMaterialCount});Write();}
    static void Capture(string name,Camera camera){var old=camera.targetTexture;var oldActive=RenderTexture.active;var rt=RenderTexture.GetTemporary(1280,720,24);var image=new Texture2D(1280,720,TextureFormat.RGB24,false);try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(Path.Combine(Reports,"shader-perf-"+result.version+"-"+name+".png"),image.EncodeToPNG());}finally{camera.targetTexture=old;RenderTexture.active=oldActive;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.Destroy(image);}}
    static string MaterialState(Material m)=>"shader="+m.shader.name+" id="+m.shader.GetInstanceID()+" supported="+m.shader.isSupported+" queue="+m.renderQueue+" tag="+m.GetTag("RecoveryProbe",false)+" color="+m.GetColor("_BaseColor");
    static async UniTaskVoid Run(){result=new Result{utc=DateTime.UtcNow.ToString("o"),version=SessionState.GetString(Key+"version",""),stage="BOOTSTRAP",profile=Application.persistentDataPath,gpu=SystemInfo.graphicsDeviceName,api=SystemInfo.graphicsDeviceType.ToString()};try{if(!result.profile.Contains("WorldRepair QA"))throw new Exception("Isolated QA required");Application.runInBackground=true;QualitySettings.vSyncCount=0;Application.targetFrameRate=-1;Write();await Wait(()=>{Prior("Dismiss");return IslandFrontEndFlow.Active&&IslandFrontEndFlow.Active.BackdropLoaded;});await Pause(1);await Singleton<MainMenuManager>.Instance.CustomizationSceneHost.PreloadAsync();IslandFrontEndFlow.Active.ShowLoadGames();await Pause(1);Resources.FindObjectsOfTypeAll<SaveSlot>().Where(s=>s&&s.gameObject.scene.name=="MainMenuState"&&s.ContainsSave).OrderBy(s=>s.SlotIndex).First().LaunchOriginalSlot();await Wait(()=>(bool)Prior("Ready"));await Pause(4);result.ready=true;result.width=Screen.width;result.height=Screen.height;
        await SampleFrames("PLAYER_VIEW");Capture("player",(Camera)Prior("WorldCamera"));
        var tablet=Resources.FindObjectsOfTypeAll<TabletController>().First(t=>t&&t.gameObject.scene.isLoaded);typeof(TabletController).GetMethod("OpenTablet",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(tablet,null);var map=tablet.MapApplication;map.Show();var live=map.GetComponent<LiveSceneTabletMap>();await Wait(()=>live.RenderedFrames>3,20);int first=live.RenderedFrames;await SampleFrames("LIVE_MAP_OPEN");result.mapUpdates=live.RenderedFrames>first+5;Capture("map",live.MapCamera);tablet.CloseTablet();await SampleFrames("MAP_CLOSED");
        result.shaders=OriginalNativeShaderRestoration.LoadedShaderCount;result.appliedMaterials=OriginalNativeShaderRestoration.AppliedMaterials;
        if(result.version=="fixed"){
            var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/Material/M_asphalt_01 1.mat");var proxy=AssetDatabase.FindAssets("t:Shader").Select(g=>AssetDatabase.LoadAssetAtPath<Shader>(AssetDatabase.GUIDToAssetPath(g))).First(s=>s&&s.name==source.shader.name);var probe=new Material(source){name="TemporaryLateShaderBindingProbe"};probe.shader=proxy;probe.renderQueue=2451;probe.SetOverrideTag("RecoveryProbe","retained");Color color=new Color(.23f,.47f,.81f,.77f);probe.SetColor("_BaseColor",color);var cube=GameObject.CreatePrimitive(PrimitiveType.Cube);cube.name="TemporaryLateShaderBindingProbe";cube.transform.position=new Vector3(0,-500,0);cube.GetComponent<Renderer>().sharedMaterial=probe;
            typeof(OriginalNativeShaderRestoration).GetMethod("RequestRefresh").Invoke(null,null);await Pause(.5);result.lateMaterialRestored=probe.shader!=proxy&&probe.shader.name==proxy.name&&probe.renderQueue==2451&&probe.GetTag("RecoveryProbe",false)=="retained"&&probe.GetColor("_BaseColor")==color;
            probe.shader=proxy;probe.renderQueue=2451;long beforeTarget=OriginalNativeShaderRestoration.ScanCount;typeof(OriginalNativeShaderRestoration).GetMethod("RestoreMaterial").Invoke(null,new object[]{probe});result.targetedMaterialRestored=probe.shader!=proxy&&OriginalNativeShaderRestoration.ScanCount==beforeTarget;
            OriginalNativeShaderRestoration.RestoreSerializedReferences();result.saveAuthoringState=MaterialState(probe)+" expectedProxy="+proxy.GetInstanceID()+" expectedColor="+color;bool restored=probe.shader==proxy&&probe.renderQueue==2451&&probe.GetTag("RecoveryProbe",false)=="retained"&&probe.GetColor("_BaseColor")==color;await Pause(.5);result.saveReappliedState=MaterialState(probe);result.saveBoundaryRetained=restored&&probe.shader!=proxy;
            probe.shader=proxy;var previousScene=SceneManager.GetActiveScene();var temporary=SceneManager.CreateScene("TemporaryShaderBindingScene");SceneManager.MoveGameObjectToScene(cube,temporary);SceneManager.SetActiveScene(temporary);await Pause(.6);result.sceneEventRestored=probe.shader!=proxy;SceneManager.SetActiveScene(previousScene);await SceneManager.UnloadSceneAsync(temporary).ToUniTask();UnityEngine.Object.Destroy(probe);
            const string diskPath="Assets/RecoveryVerification/ShaderPerformanceMaterialProbe-20261020.mat";
            if(File.Exists(diskPath))throw new Exception("Refusing to overwrite prior material probe");
            var disk=new Material(source){name="Shader performance persistence probe",renderQueue=2451};disk.SetOverrideTag("RecoveryProbe","retained");disk.SetColor("_BaseColor",color);
            try{AssetDatabase.CreateAsset(disk,diskPath);EditorUtility.SetDirty(disk);AssetDatabase.SaveAssets();string raw=File.ReadAllText(diskPath);File.WriteAllText(Path.Combine(Reports,"shader-performance-material-save-probe.txt"),raw);AssetDatabase.ImportAsset(diskPath,ImportAssetOptions.ForceUpdate);disk=AssetDatabase.LoadAssetAtPath<Material>(diskPath);string guid=AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(proxy));result.diskMaterialRetained=raw.Contains("guid: "+guid)&&disk.renderQueue==2451&&disk.GetTag("RecoveryProbe",false)=="retained"&&disk.GetColor("_BaseColor")==color;}finally{AssetDatabase.DeleteAsset(diskPath);}
            await Pause(1);
            result.unrestoredMaterials=UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None).SelectMany(r=>r.sharedMaterials).Where(m=>m&&m.shader&&!m.shader.isSupported).Select(m=>m.name).Distinct().Count();var features=Resources.FindObjectsOfTypeAll<StylizedWater3.StylizedWaterRenderFeature>();result.waterComputeRestored=features.Length>0&&features.All(f=>f.heightReadbackCS==(ComputeShader)typeof(OriginalNativeShaderRestoration).GetField("originalHeightSampler",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null));
        }
    }catch(Exception e){result.error=e.ToString();}finally{result.stage="EXITING_PLAY";Write();SessionState.SetBool(Key+"done",true);EditorApplication.ExitPlaymode();}}
}
